/*
 * Assemble adaptive trace identity, feasibility counts, refresh settings and constraint-guard statistics.
 * emit_trace passes the current record while run_ supplies population and generation-boundary counters.
 * Preserve row counting and guard-statistic interpretation without modifying the observed optimizer state.
 */
// Generated by split_adaptive_diagnostics.py; complete trace field methods.
#include "adaptive_session.hpp"

namespace optiland { namespace optimizer_detail {


void AdaptiveSession::count_trace_feasibility(int& feasible_count, int& trace_feasible_count, int& constraint_feasible_count, int& first_order_feasible_count) {
        for (const auto& item : run_.fitness) {
            feasible_count += item.feasible ? 1 : 0;
            trace_feasible_count += item.trace_feasible ? 1 : 0;
            constraint_feasible_count += item.constraint_feasible ? 1 : 0;
            first_order_feasible_count += item.first_order_feasible ? 1 : 0;
        }
}

void AdaptiveSession::assemble_trace_identity(HybridTraceEvent& trace, const std::string& event, int epoch, int event_de_generations) {
        trace.event = event;
        trace.epoch = epoch;
        trace.population_size = run_.pop_size;
        trace.variable_count = run_.dim;
        trace.de_generations = run_.total_de_generations;
        trace.epoch_de_generations = event_de_generations;
        trace.parent_count = run_.requested_polish_count;
}

void AdaptiveSession::assemble_trace_refresh(HybridTraceEvent& trace, int event_refreshed_count, int event_accepted_trials, int event_refresh_archive_used, int event_refresh_effective_count, bool event_refresh_adaptive_skipped, double event_refresh_acceptance_rate, double event_refresh_rel_improvement) {
        const int trace_refresh_count =
            options.refresh_generation.target_count > 0
                ? options.refresh_generation.target_count
                : static_cast<int>(std::round(std::max(0.0, options.refresh_fraction) * run_.pop_size));
        trace.refresh_count = std::clamp(
            trace_refresh_count,
            0,
            std::max(0, run_.pop_size - 1));
        trace.refreshed_count = event_refreshed_count;
        trace.refresh_archive_size =
            static_cast<int>(run_.traceable_refresh_archive.size());
        trace.refresh_archive_used = event_refresh_archive_used;
        trace.refresh_effective_count =
            event_refresh_effective_count >= 0
                ? event_refresh_effective_count
                : trace.refresh_count;
        trace.refresh_adaptive_skipped = event_refresh_adaptive_skipped;
        trace.refresh_acceptance_rate = event_refresh_acceptance_rate;
        trace.refresh_rel_improvement = event_refresh_rel_improvement;
        trace.accepted_trials = event_accepted_trials;
}

void AdaptiveSession::assemble_trace_constraint_guards(HybridTraceEvent& trace) {
        trace.efl_sign_priority_target = owner.merit_config_.target_efl;
        trace.efl_sign_priority_promoted_trial_count =
            run_.epoch_efl_sign_priority_promoted_trial_count;
        trace.efl_sign_priority_blocked_trial_count =
            run_.epoch_efl_sign_priority_blocked_trial_count;
        if (options.cra_worsening_guard_enabled) {
            trace.cra_worsening_guard_upper_deg =
                options.cra_worsening_guard_target_deg +
                options.cra_worsening_guard_tolerance_deg;
        }
        trace.cra_worsening_guard_blocked_trial_count =
            run_.epoch_cra_worsening_guard_blocked_trial_count;
        if (options.joint_constraint_anchor_guard_enabled) {
            trace.joint_constraint_anchor_cra_activation_upper_deg =
                options.joint_constraint_anchor_cra_target_deg +
                options.joint_constraint_anchor_cra_tolerance_deg;
            trace.joint_constraint_anchor_distortion_activation_upper =
                options.joint_constraint_anchor_distortion_target +
                options.joint_constraint_anchor_distortion_tolerance;
            trace.joint_constraint_anchor_active_count = static_cast<int>(
                std::count_if(
                    run_.joint_constraint_anchors.begin(),
                    run_.joint_constraint_anchors.end(),
                    [](const JointConstraintAnchorState& anchor) {
                        return anchor.active;
                    }));
        }
        trace.joint_constraint_anchor_activated_count =
            run_.epoch_joint_constraint_anchor_activated_count;
        trace.joint_constraint_anchor_updated_count =
            run_.epoch_joint_constraint_anchor_updated_count;
        trace.joint_constraint_anchor_blocked_cra_count =
            run_.epoch_joint_constraint_anchor_blocked_cra_count;
        trace.joint_constraint_anchor_blocked_distortion_count =
            run_.epoch_joint_constraint_anchor_blocked_distortion_count;
        trace.joint_constraint_anchor_blocked_both_count =
            run_.epoch_joint_constraint_anchor_blocked_both_count;
        if (std::isfinite(owner.merit_config_.target_efl) &&
            std::abs(owner.merit_config_.target_efl) > 1.0e-12) {
            for (const auto& item : run_.fitness) {
                if (efl_sign_matches_target(
                        item.score.efl,
                        owner.merit_config_.target_efl)) {
                    ++trace.efl_sign_matching_population_count;
                } else if (std::isfinite(item.score.efl) &&
                           std::abs(item.score.efl) > 1.0e-12) {
                    ++trace.efl_sign_opposite_population_count;
                } else {
                    ++trace.efl_sign_unknown_population_count;
                }
            }
        } else {
            trace.efl_sign_unknown_population_count =
                static_cast<int>(run_.fitness.size());
        }
}


} } // namespace optiland::optimizer_detail
